class Solution:
    def rebuildLine(self, people: List[List[int]]) -> List[List[int]]:
        n = len(people)
        line = [None] * n
        for h, k in sorted(people, key=lambda p: (p[0], -p[1])):
            empty = -1
            for i in range(n):
                if line[i] is None:
                    empty += 1
                    if empty == k:
                        line[i] = [h, k]
                        break
        return line

