class Solution {
    public int[][] rebuildLine(int[][] people) {
        int n = people.length;
        int[][] line = new int[n][];
        int[][] a = people.clone();
        Arrays.sort(a, (x, y) -> x[0] != y[0] ? x[0] - y[0] : y[1] - x[1]);
        for (int[] p : a) {
            int empty = -1;
            for (int i = 0; i < n; i++)
                if (line[i] == null && ++empty == p[1]) { line[i] = new int[] {p[0], p[1]}; break; }
        }
        return line;
    }
}

