class Solution {
public:
    vector<vector<int>> rebuildLine(vector<vector<int>>& people) {
        int n = people.size();
        vector<vector<int>> line(n);
        vector<vector<int>> a = people;
        sort(a.begin(), a.end(), [](auto& x, auto& y) { return x[0] != y[0] ? x[0] < y[0] : x[1] > y[1]; });
        for (auto& p : a) {
            int empty = -1;
            for (int i = 0; i < n; i++)
                if (line[i].empty() && ++empty == p[1]) { line[i] = p; break; }
        }
        return line;
    }
};

