static int shortest_first(const void* x, const void* y) {
    const int *a = *(int* const*) x, *b = *(int* const*) y;
    return a[0] != b[0] ? a[0] - b[0] : b[1] - a[1];
}

int** rebuildLine(int** people, int peopleSize, int* peopleColSize, int* returnSize, int** returnColumnSizes) {
    int n = peopleSize;
    int** line = calloc(n, sizeof(int*));
    int** a = malloc(n * sizeof(int*));
    memcpy(a, people, n * sizeof(int*));
    qsort(a, n, sizeof(int*), shortest_first);
    for (int p = 0; p < n; p++) {
        int empty = -1;
        for (int i = 0; i < n; i++)
            if (!line[i] && ++empty == a[p][1]) {
                line[i] = malloc(2 * sizeof(int));
                line[i][0] = a[p][0];
                line[i][1] = a[p][1];
                break;
            }
    }
    free(a);
    *returnSize = n;
    *returnColumnSizes = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) (*returnColumnSizes)[i] = 2;
    return line;
}

