class Solution {
public:
    vector<vector<int>> rebuildLine(vector<vector<int>>& people) {
        vector<vector<int>> a = people;
        sort(a.begin(), a.end(), [](auto& x, auto& y) { return x[0] != y[0] ? x[0] > y[0] : x[1] < y[1]; });
