static int tallest_first(const void* x, const void* y) {
    const int *a = *(int* const*) x, *b = *(int* const*) y;
    return a[0] != b[0] ? b[0] - a[0] : a[1] - b[1];
}

int** rebuildLine(int** people, int peopleSize, int* peopleColSize, int* returnSize, int** returnColumnSizes) {
    int n = peopleSize;
    int** a = malloc(n * sizeof(int*));
    memcpy(a, people, n * sizeof(int*));
    qsort(a, n, sizeof(int*), tallest_first);
    int** line = malloc(n * sizeof(int*));
    for (int p = 0; p < n; p++) {
        int k = a[p][1];
        memmove(line + k + 1, line + k, (p - k) * sizeof(int*));
        line[k] = malloc(2 * sizeof(int));
        line[k][0] = a[p][0];
        line[k][1] = k;
    }
    free(a);
    *returnSize = n;
    *returnColumnSizes = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) (*returnColumnSizes)[i] = 2;
    return line;
}
